-- 04_CMBO_SYNC.sql — DMF0042 소비 콤보 전수 현행 스냅샷 (MERGE 멱등. ⚠ 공유 콤보 포함 — 타 화면 소비분과 동일 원장)
SET DEFINE OFF

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'MyDivision' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='MyDivision', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('MyDivision', 'DM', 'MyDivision', TO_CLOB('  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'UserTeamByDivision' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='DMF0003 UserTeamByDivision (AS-IS BigFilter/UP_FX 1:1)', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT A.DIVISION_ID AS DIVISION_ID, C.DEPT_ID AS CODE
     , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME
FROM SCM_MST_SITE_ITEM A, SCM_MST_SSO_USER_INFO B, SCM_MST_SSO_DEPT_INFO C
WHERE B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))
  AND B.DEPT_ID = C.DEPT_ID
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
ORDER BY DIVISION_ID, NAME, CODE'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('UserTeamByDivision', 'DM', 'DMF0003 UserTeamByDivision (AS-IS BigFilter/UP_FX 1:1)', TO_CLOB('SELECT DISTINCT A.DIVISION_ID AS DIVISION_ID, C.DEPT_ID AS CODE
     , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME
FROM SCM_MST_SITE_ITEM A, SCM_MST_SSO_USER_INFO B, SCM_MST_SSO_DEPT_INFO C
WHERE B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))
  AND B.DEPT_ID = C.DEPT_ID
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
ORDER BY DIVISION_ID, NAME, CODE'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'EndCustomer' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='EndCustomer', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, DEPT_ID, CODE'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomer', 'DM', 'EndCustomer', TO_CLOB('SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, DEPT_ID, CODE'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'EndCustomerByDivision40' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='[C] AS-IS @Code=''EndCustomerByDivision40'' 수작업 통합 변환 — 빈 파라미터 0행 함정 ', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT C.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MGR.SCM_MST_SITE_ITEM A
JOIN SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0 THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END)
JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y''
UNION
SELECT NULL AS DEPT_ID, SEGMENT2, SEGMENT3 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40'' AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y''
ORDER BY 2'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomerByDivision40', 'DM', '[C] AS-IS @Code=''EndCustomerByDivision40'' 수작업 통합 변환 — 빈 파라미터 0행 함정 ', TO_CLOB('SELECT DISTINCT C.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MGR.SCM_MST_SITE_ITEM A
JOIN SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0 THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END)
JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y''
UNION
SELECT NULL AS DEPT_ID, SEGMENT2, SEGMENT3 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40'' AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y''
ORDER BY 2'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'BizTypeByDivision' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='Biz Type by Division (AS-IS SCM0001_GET_BIZ_TYPE_BY_DIVISION 1:1 — @divisionId)', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT BIZ_TYPE AS CODE, BIZ_TYPE_NAME AS NAME
FROM SCM_MST_PROJECT
WHERE TRIM(BIZ_TYPE_NAME) IS NOT NULL
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || DIVISION_ID || '','') > 0)
ORDER BY CODE'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('BizTypeByDivision', 'CM', 'Biz Type by Division (AS-IS SCM0001_GET_BIZ_TYPE_BY_DIVISION 1:1 — @divisionId)', TO_CLOB('SELECT DISTINCT BIZ_TYPE AS CODE, BIZ_TYPE_NAME AS NAME
FROM SCM_MST_PROJECT
WHERE TRIM(BIZ_TYPE_NAME) IS NOT NULL
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || DIVISION_ID || '','') > 0)
ORDER BY CODE'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'DmBizType' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='DM_BIZ_TYPE', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''DM_BIZ_TYPE''
ORDER BY DISPLAY_SEQ'),
