WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('DmBizType', 'DM', 'DM_BIZ_TYPE', TO_CLOB('SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''DM_BIZ_TYPE''
ORDER BY DISPLAY_SEQ'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'ItemType' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='Item Type', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT        L.SEGMENT1  AS CODE,        L.SEGMENT2  AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE  1 = 1 AND    L.LOOKUP_TYPE = ''ITEM_TYPE_CODE'' AND    L.VALID_YN    = ''Y'' ORDER BY L.DISPLAY_SEQ'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('ItemType', 'DM', 'Item Type', TO_CLOB('SELECT        L.SEGMENT1  AS CODE,        L.SEGMENT2  AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE  1 = 1 AND    L.LOOKUP_TYPE = ''ITEM_TYPE_CODE'' AND    L.VALID_YN    = ''Y'' ORDER BY L.DISPLAY_SEQ'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'BucketType2' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
