MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'PlantSitebyEndCustomer' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='[C] AS-IS @Code=''PlantSitebyEndCustomer'' 수작업 통합 변환 — auth-ext 제거 + 빈 파라미', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0) ORDER BY CODE'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('PlantSitebyEndCustomer', 'DM', '[C] AS-IS @Code=''PlantSitebyEndCustomer'' 수작업 통합 변환 — auth-ext 제거 + 빈 파라미', TO_CLOB('SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0) ORDER BY CODE'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'UserSiteByEndCustomer' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='Sales Site (AS-IS UP_FX SiteByEndCustomer/40 1:1 — @divisionId/@endCustomer/@deptId/@asYn)', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT CODE, NAME FROM (
SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER
FROM SCM_MST_SITE A
WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND A.DIVISION_ID <> ''40''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2
FROM SCM_MST_SITE A
LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C
  ON B.OWNER = C.USER_ID
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)
  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID
WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y''
  AND (NVL(TRIM(@divisionId), ''A')
         || TO_CLOB('LL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)
) ORDER BY SORT_ORDER, CODE'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('UserSiteByEndCustomer', 'DM', 'Sales Site (AS-IS UP_FX SiteByEndCustomer/40 1:1 — @divisionId/@endCustomer/@deptId/@asYn)', TO_CLOB('SELECT CODE, NAME FROM (
SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER
FROM SCM_MST_SITE A
WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND A.DIVISION_ID <> ''40''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2
FROM SCM_MST_SITE A
LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C
  ON B.OWNER = C.USER_ID
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)
  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID
WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y''
  AND (NVL(TRIM(@divisionId), ''A')
         || TO_CLOB('LL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)
) ORDER BY SORT_ORDER, CODE'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'CurrencyList' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='통화 list', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT SEGMENT1 AS CODE, 		SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE  (LOOKUP_TYPE = ''CURRENCY_LIST'') AND  VALID_YN = ''Y'' ORDER BY  DISPLAY_SEQ'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
