MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'EndCustomerByDivisionDept' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='End Customer by division, team', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomerByDivisionDept', 'DM', 'End Customer by division, team', TO_CLOB('SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING (SELECT 'SiteByEndCustomer' AS SQL_ID FROM DUAL) S ON (T.SQL_ID = S.SQL_ID)
WHEN MATCHED THEN UPDATE SET SQL_NM='SCM Site by End Customer', USE_YN='Y', SQL_DTL_CTN=TO_CLOB('SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID, 	A.END_CUSTOMER AS END_CUSTOMER,     A.SCM_SITE_ID AS CODE,     A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B     ON (@divisionId = ''40'' AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID) LEFT JOIN (     SELECT REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) AS token     FROM DUAL     CONNECT BY REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) IS NOT NULL ) C ON (1=1) WHERE A.SITE_TYPE = ''SALES''   AND A.VALID_YN = ''Y''   AND (         @divisionId IS NULL         OR @divisionId = ''''         OR @divisionId = ''ALL''         OR A.DIVISION_ID IN (             SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL)             FROM DUAL             CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL         )       )   AND (         @endCustomer IS NULL         OR @endCustomer = ''''         OR @endCustomer = ''ALL''         OR (             @divisionId <> ''40''             AND A.END_CUSTOMER = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN A.END_CUSTOMER                 ELSE C.token             END         )         OR (             @divisionId = ''40''             AND B.PROJECT_CODE = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN B.PROJECT_CODE                 ELSE C.token             END         )       )   AND A.DIVISION_ID IN (         SELECT DISTINCT UNIT_ID         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M         WHERE USER_ID = @sesUserId           AND UNIT_TP_CD = ''D''     ) ORDER BY A.SCM_SITE_ID ASC'),
     LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('SiteByEndCustomer', 'DM', 'SCM Site by End Customer', TO_CLOB('SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID, 	A.END_CUSTOMER AS END_CUSTOMER,     A.SCM_SITE_ID AS CODE,     A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B     ON (@divisionId = ''40'' AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID) LEFT JOIN (     SELECT REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) AS token     FROM DUAL     CONNECT BY REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) IS NOT NULL ) C ON (1=1) WHERE A.SITE_TYPE = ''SALES''   AND A.VALID_YN = ''Y''   AND (         @divisionId IS NULL         OR @divisionId = ''''         OR @divisionId = ''ALL''         OR A.DIVISION_ID IN (             SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL)             FROM DUAL             CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL         )       )   AND (         @endCustomer IS NULL         OR @endCustomer = ''''         OR @endCustomer = ''ALL''         OR (             @divisionId <> ''40''             AND A.END_CUSTOMER = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN A.END_CUSTOMER                 ELSE C.token             END         )         OR (             @divisionId = ''40''             AND B.PROJECT_CODE = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN B.PROJECT_CODE                 ELSE C.token             END         )       )   AND A.DIVISION_ID IN (         SELECT DISTINCT UNIT_ID         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M         WHERE USER_ID = @sesUserId           AND UNIT_TP_CD = ''D''     ) ORDER BY A.SCM_SITE_ID ASC'), 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

